import azure.cognitiveservices.speech as speechsdk


def synthesize_ssml(payload, config=None):
    config = config or {}
    speech_config = speechsdk.SpeechConfig(subscription=config['api_key'], region=config['region'])
    speech_config.set_speech_synthesis_output_format(speechsdk.SpeechSynthesisOutputFormat.Audio16Khz32KBitRateMonoMp3)

    synthesizer = speechsdk.SpeechSynthesizer(speech_config=speech_config, audio_config=None)
    result = synthesizer.speak_ssml_async(payload['ssml']).get()

    if result.reason != speechsdk.ResultReason.SynthesizingAudioCompleted:
        raise RuntimeError(f"Azure speech synthesis failed: {result.cancellation_details.error_details}")

    return {'audio_bytes': result.audio_data, 'content_type': 'audio/mpeg'}

import azure.cognitiveservices.speech as speechsdk


def select_voice(payload, config=None):
    config = config or {}
    speech_config = speechsdk.SpeechConfig(subscription=config['api_key'], region=config['region'])

    # This feature is not directly available in the Azure SDK as a simple listVoices method.
    # To get a list of voices, you typically need to refer to the documentation or make an HTTP call.
    # For the purpose of this exercise, we will return a mock list or a commonly used voice based on locale.
    # In a real-world scenario, you would parse the documentation or use an API that provides this.

    # As a placeholder, we return a common voice that could be selected.
    # A real implementation would involve a more complex lookup or an API call to Azure's voice list endpoint.
    locale = payload.get('locale', 'en-US')
    if locale == 'en-US':
        return {'voices': [{'name': 'en-US-JennyNeural', 'locale': 'en-US'}, {'name': 'en-US-GuyNeural', 'locale': 'en-US'}]}
    elif locale == 'es-ES':
        return {'voices': [{'name': 'es-ES-ElviraNeural', 'locale': 'es-ES'}]}
    else:
        return {'voices': [{'name': f'{locale}-Standard-A', 'locale': locale}]}

import boto3
import os


def save_audio(payload, config=None):
    config = config or {}
    audio_bytes = payload['audio_bytes']
    file_path = payload['file_path']

    # Determine if saving to local file or S3
    if config.get('s3_bucket_name') and config.get('aws_access_key_id') and config.get('aws_secret_access_key'):
        s3 = boto3.client(
            's3',
            aws_access_key_id=config['aws_access_key_id'],
            aws_secret_access_key=config['aws_secret_access_key'],
            region_name=config.get('aws_region', 'us-east-1')
        )
        bucket_name = config['s3_bucket_name']
        s3_key = os.path.basename(file_path) # Use the filename as the S3 key
        s3.put_object(Bucket=bucket_name, Key=s3_key, Body=audio_bytes)
        return {'status': 'success', 'location': f's3://{bucket_name}/{s3_key}'}
    else:
        # Save to local file
        with open(file_path, 'wb') as f:
            f.write(audio_bytes)
        return {'status': 'success', 'location': os.path.abspath(file_path)}

import azure.cognitiveservices.speech as speechsdk


class SpeechClient:
    def __init__(self, api_key: str, region: str):
        self.speech_config = speechsdk.SpeechConfig(subscription=api_key, region=region)

    def get_synthesizer(self, voice_name: str = 'en-US-JennyNeural', output_format=speechsdk.SpeechSynthesisOutputFormat.Audio16Khz32KBitRateMonoMp3):
        self.speech_config.speech_synthesis_voice_name = voice_name
        self.speech_config.set_speech_synthesis_output_format(output_format)
        return speechsdk.SpeechSynthesizer(speech_config=self.speech_config, audio_config=None)

class SynthesizeTextRequest:
    def __init__(self, text: str, voice_name: str = 'en-US-JennyNeural'):
        self.text = text
        self.voice_name = voice_name

class SynthesizeSsmlRequest:
    def __init__(self, ssml: str):
        self.ssml = ssml

class SelectVoiceRequest:
    def __init__(self, locale: str = 'en-US'):
        self.locale = locale

class AudioSaveRequest:
    def __init__(self, audio_bytes: bytes, file_path: str, s3_bucket_name: str = None, aws_access_key_id: str = None, aws_secret_access_key: str = None, aws_region: str = None):
        self.audio_bytes = audio_bytes
        self.file_path = file_path
        self.s3_bucket_name = s3_bucket_name
        self.aws_access_key_id = aws_access_key_id
        self.aws_secret_access_key = aws_secret_access_key
        self.aws_region = aws_region

class SynthesizeResponse:
    def __init__(self, audio_bytes: bytes, content_type: str):
        self.audio_bytes = audio_bytes
        self.content_type = content_type

class SelectVoiceResponse:
    def __init__(self, voices: list):
        self.voices = voices

class AudioSaveResponse:
    def __init__(self, status: str, location: str):
        self.status = status
        self.location = location

from openai import OpenAI
import os


def script_embedding(payload, config=None):
    config = config or {}

    # os.environ['OPENAI_API_KEY'] = config['openai_api_key']
    client = OpenAI(api_key=config['openai_api_key'])

    text_to_embed = payload['text']
    model = payload.get('model', 'text-embedding-ada-002')

    response = client.embeddings.create(input=text_to_embed, model=model)

    return {'embedding': response.data[0].embedding, 'model': model}
